import{_ as e,o as n,c as a,a4 as i}from"./chunks/framework.DPwo9VAo.js";const p=JSON.parse('{"title":"Tối ưu hóa hiệu năng (Performance Optimization)","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/performance.md","filePath":"advanced/performance.md","lastUpdated":1795338762000}'),s={name:"advanced/performance.md"};function o(l,t,h,r,c,d){return n(),a("div",null,t[0]||(t[0]=[i(`<h1 id="toi-uu-hoa-hieu-nang-performance-optimization" tabindex="-1">Tối ưu hóa hiệu năng (Performance Optimization) <a class="header-anchor" href="#toi-uu-hoa-hieu-nang-performance-optimization" aria-label="Permalink to &quot;Tối ưu hóa hiệu năng (Performance Optimization)&quot;">​</a></h1><p>Tài liệu này tổng hợp các chiến lược tối ưu hóa để đảm bảo ứng dụng Web GIS xử lý mượt mà lượng dữ liệu không gian lớn (hàng trăm nghìn điểm/đa giác) mà không bị sụt giảm fps.</p><hr><h2 id="_1-su-dung-vector-tiles-thay-cho-geojson-voi-tap-du-lieu-lon" tabindex="-1">1. Sử dụng Vector Tiles thay cho GeoJSON với tập dữ liệu lớn <a class="header-anchor" href="#_1-su-dung-vector-tiles-thay-cho-geojson-voi-tap-du-lieu-lon" aria-label="Permalink to &quot;1. Sử dụng Vector Tiles thay cho GeoJSON với tập dữ liệu lớn&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tiêu chí</th><th style="text-align:left;">GeoJSON</th><th style="text-align:left;">Vector Tiles (MVT / PMTiles)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Dung lượng nạp</strong></td><td style="text-align:left;">Tải toàn bộ file một lần (ví dụ: 50MB)</td><td style="text-align:left;">Chỉ tải các tile trong khung nhìn (Viewport)</td></tr><tr><td style="text-align:left;"><strong>Xử lý CPU</strong></td><td style="text-align:left;">Main thread phải parse JSON text nặng</td><td style="text-align:left;">Tile dạng nhị phân protobuf (PBF) nạp cực nhanh</td></tr><tr><td style="text-align:left;"><strong>Giới hạn khuyến nghị</strong></td><td style="text-align:left;">&lt; 50,000 features</td><td style="text-align:left;">Không giới hạn (hàng triệu features)</td></tr></tbody></table><blockquote><p><strong>Quy tắc vàng</strong>: Nếu tập dữ liệu của bạn vượt quá 5MB hoặc 20,000 đối tượng, hãy chuyển đổi sang Vector Tiles (<code>@hungpvq/map-dataset/vector-tile</code>).</p></blockquote><hr><h2 id="_2-tach-tac-vu-tinh-toan-sang-web-worker" tabindex="-1">2. Tách tác vụ tính toán sang Web Worker <a class="header-anchor" href="#_2-tach-tac-vu-tinh-toan-sang-web-worker" aria-label="Permalink to &quot;2. Tách tác vụ tính toán sang Web Worker&quot;">​</a></h2><p>Khi xử lý các file KML, Shapefile, tính toán buffer hoặc chuyển đổi hệ tọa độ VN-2000 qua WGS84, Main Thread sẽ bị nghẽn (UI freeze).</p><p>Sử dụng GIS Worker tích hợp sẵn trong <code>@hungpvq/map-dataset/geojson</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { loadGeojsonFileAsync, configureGisWorker } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/map-dataset/geojson&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Tự động phân tích file nặng trong background thread</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> geojsonData</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loadGeojsonFileAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(largeShapefileZip);</span></span></code></pre></div><hr><h2 id="_3-toi-uu-hoa-layer-styling-paint-properties" tabindex="-1">3. Tối ưu hóa Layer Styling &amp; Paint Properties <a class="header-anchor" href="#_3-toi-uu-hoa-layer-styling-paint-properties" aria-label="Permalink to &quot;3. Tối ưu hóa Layer Styling &amp; Paint Properties&quot;">​</a></h2><ol><li><strong>Tránh đổi Paint properties liên tục từng frame</strong>: Thay vì dùng vòng lặp <code>setInterval</code> để đổi màu, hãy sử dụng Feature State (<code>map.setFeatureState</code>) hoặc Data-driven styling (<code>[&#39;case&#39;, ...]</code>).</li><li><strong>Sử dụng Simplified Geometries ở các mức zoom nhỏ</strong>: Dùng hàm <code>simplify</code> của Turf để giảm số lượng đỉnh khi người dùng nhìn ở mức zoom xa.</li><li><strong>Bật thuộc tính <code>trackResize: false</code></strong> nếu vùng chứa bản đồ có kích thước cố định để giảm thiểu số lần tính toán bounding box của trình duyệt.</li></ol>`,14)]))}const u=e(s,[["render",o]]);export{p as __pageData,u as default};
